  "name": "company-website",
  "version": "1.0.0",
  "description": "企业官网",
  "scripts": {
    "start": "npx serve -s public -p $PORT",
    "dev": "npx serve -s public -p 3000"
  },
  "dependencies": {
    "serve": "^14.2.0"
  }
}

